import 'dart:io';import 'dart:convert';import 'package:storage_io_flight_recorder/storage_io_flight_recorder.dart';
Future<void> main(List<String> args)async{final c=await Client.open(libraryPath:args.isEmpty?null:args[0]);try{var rejected=false;try{c.call('check');}on NativeException{rejected=true;}if(!rejected)throw StateError('Invalid request accepted');if(args.isNotEmpty){final tests=jsonDecode(File('doc/contract.json').readAsStringSync()) as List;for(final test in tests){final result=c.call(test['operation'] as String,Map<String,dynamic>.from(test['arguments'] as Map));final value=result[test['expected_key']];if(test.containsKey('expected_value') && value!=test['expected_value'])throw StateError('Wrong result');if(test.containsKey('minimum_length') && (value as List).length<(test['minimum_length'] as int))throw StateError('Array missing');}}}finally{c.close();}}
